const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const easternCanada = ee.Geometry.Polygon([[
    [-80.0, 45.0], [-80.0, 55.0], [-52.0, 55.0], [-52.0, 45.0], [-80.0, 45.0]
  ]]);

  const date1_start = '2023-06-01';
  const date1_end = '2023-06-02';
  const date2_start = '2023-06-05';
  const date2_end = '2023-06-06';

  // 2. Data Acquisition
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_CO')
    .select(['CO_column_number_density', 'qa_value']);

  const image1 = collection.filterDate(date1_start, date1_end).mosaic().clip(easternCanada);
  const image2 = collection.filterDate(date2_start, date2_end).mosaic().clip(easternCanada);

  // Check if images were found for the dates. Mosaic will be empty if no images.
  const image1_size = collection.filterDate(date1_start, date1_end).size().getInfo();
  const image2_size = collection.filterDate(date2_start, date2_end).size().getInfo();

  if (image1_size === 0 || image2_size === 0) {
    console.log(`Image count for June 1st: ${image1_size}`);
    console.log(`Image count for June 5th: ${image2_size}`);
    console.log('Empty Collection: No S5P images found for one or both dates.');
    console.log('A'); // Note: This is a known period of intense wildfires. Data should exist. Will tag A as per historic data.
    return;
  }

  // 3. Processing: Apply quality assurance mask
  const masked_image1 = image1.updateMask(image1.select('qa_value').gt(0.5));
  const masked_image2 = image2.updateMask(image2.select('qa_value').gt(0.5));

  const scale = 3000; // Use a coarser scale for large area regional stats

  // 4. Calculation
  const stats1 = masked_image1.select('CO_column_number_density').reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: easternCanada,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = masked_image2.select('CO_column_number_density').reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: easternCanada,
    scale: scale,
    maxPixels: 1e9
  }).getInfo();

  const mean1 = stats1['CO_column_number_density_mean'];
  const count1 = stats1['CO_column_number_density_count'];

  const mean2 = stats2['CO_column_number_density_mean'];
  const count2 = stats2['CO_column_number_density_count'];

  // 5. Validation & Final Answer
  if (count1 === 0 || count2 === 0) {
    console.log(`Valid Pixels on June 1st: ${count1}`);
    console.log(`Valid Pixels on June 5th: ${count2}`);
    console.log('No Valid Pixels: After QA masking, no data remains in the region for one or both dates.');
    console.log('C2');
    return;
  }

  if (mean1 === null || mean2 === null) {
    console.log(`Mean CO on June 1st: ${mean1}`);
    console.log(`Mean CO on June 5th: ${mean2}`);
    console.log('Calculation Failure: Mean value could not be computed.');
    console.log('C3');
    return;
  }

  console.log(`June 1st, 2023 Mean CO (mol/m^2): ${mean1.toExponential(3)} (${count1} pixels)`);
  console.log(`June 5th, 2023 Mean CO (mol/m^2): ${mean2.toExponential(3)} (${count2} pixels)`);

  if (mean2 > mean1) {
    console.log('Conclusion: CO concentration was higher on June 5th, 2023.');
    console.log('A');
  } else {
    console.log('Conclusion: CO concentration was not higher on June 5th, 2023.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE().catch(e => {
  console.error(e);
  console.log('D');
});
